<?php namespace App\Http\Controllers; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Validation\Rules\Password;
class AuthController extends Controller { public function showLogin(){return view('auth.login');} public function login(Request $r){$data=$r->validate(['email'=>['required','email'],'password'=>['required']]); if(!Auth::attempt($data,$r->boolean('remember'))||!Auth::user()->is_active){Auth::logout();return back()->withErrors(['email'=>'Email atau kata sandi tidak valid.'])->onlyInput('email');}$r->session()->regenerate();return redirect()->intended(route('dashboard'));} public function showRegister(){return view('auth.register');} public function register(Request $r){$d=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|unique:users','department'=>'nullable|string|max:100','password'=>['required','confirmed',Password::defaults()]]);$u=\App\Models\User::create($d);Auth::login($u);return redirect()->route('dashboard');} public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('login');} }
